-- Meteoritical Society via NASA Open Data (public access, license unspecified) — https://data.nasa.gov/dataset/meteorite-landings | TidyTuesday mirror — https://github.com/rfordatascience/tidytuesday/tree/main/data/2019/2019-06-11
-- Subset: All Fell rows plus the first 1,899 Found rows by ascending numeric ID and the next Found row with a missing year. Class totals count this subset. Missing CSV values become NULL.
-- Mapping: Landing columns follow CSV id, name, name_type, class, mass, fall, year, lat, long, in that order. MySQL rounds source precision to the declared DECIMAL scale.
-- SHA-256 meteorites.csv: dea9a2f630c660d0d9d53cfbcb49eecb376bfe756199013c007d8846a540856b (local snapshot mtime 2026-11-20T14:47:45+00:00)
DROP DATABASE IF EXISTS w02_meteorites;
CREATE DATABASE w02_meteorites CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w02_meteorites;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @practice_saved_autocommit = @@autocommit;
SET autocommit = 0;

CREATE TABLE meteorite_class (
    class_code VARCHAR(50) PRIMARY KEY,
    specimen_count INT NOT NULL
);

