CREATE TABLE meteorite_landing (
    meteorite_id INT PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    name_type VARCHAR(20),
    class_code VARCHAR(50),
    mass_g DECIMAL(12,2),
    fall_status VARCHAR(10) NOT NULL,
    landing_year INT,
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6),
    FOREIGN KEY (class_code) REFERENCES meteorite_class(class_code)
);

